import { Controller } from "@hotwired/stimulus"

// A single reaction in the strip. Only your own reactions can be expanded to
// reveal the button that removes them.
export default class extends Controller {
  static classes = [ "deleteable", "deleting", "expanded" ]

  connect() {
    if (this.#isOwn) this.element.classList.add(this.deleteableClass)
