  toggle() {
    if (this.#isOwn) this.element.classList.toggle(this.expandedClass)
  }

  remove() {
    this.element.classList.add(this.deletingClass)
  }

  get #isOwn() {
    return this.#reacterId === Current.user?.id
  }

  get #reacterId() {
    return this.element.dataset.creatorId
  }
}
